#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

static char main_out[OUT_BUF_SIZE];

static void to_camel(const char *in) {
    size_t i = 0;
    int capitalize = 0;
    for (size_t p = 0; in[p] != '\0' && i + 1 < OUT_BUF_SIZE; ++p) {
        char c = in[p];
        if (c == '_') {
            capitalize = 1;
            continue;
        }
        if (capitalize) {
            main_out[i++] = (char)toupper((unsigned char)c);
            capitalize = 0;
        } else {
            if (i == 0)
                main_out[i++] = (char)tolower((unsigned char)c);
            else
                main_out[i++] = c;
        }
    }
    main_out[i] = '\0';
}

static void to_snake(const char *in) {
    size_t i = 0;
    for (size_t p = 0; in[p] != '\0' && i + 2 < OUT_BUF_SIZE; ++p) {
        char c = in[p];
        if (isupper((unsigned char)c)) {
            if (i != 0) {
                main_out[i++] = '_';
            }
            main_out[i++] = (char)tolower((unsigned char)c);
        } else {
            main_out[i++] = c;
        }
    }
    main_out[i] = '\0';
}

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(main_out);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
